// 第五轮：登录记录 5 条/页，余额变动 10 条/页（各自独立）
let 操作留痕_登录每页数量 = 5;
let 操作留痕_余额每页数量 = 10;

async function 刷新操作留痕() {
      
    if (!开发者UID || !开发者密码) {
        alert('请先登录', false);
        return;
    }
    
    const 操作留痕_加载动画 = document.getElementById('操作留痕_加载动画');

    if (操作留痕_加载动画) 操作留痕_加载动画.style.display = 'flex';


        const params = {
            action:  'get_czlh',
            password: 开发者安全密码,
            page_余额变动: 操作留痕_余额变动_当前页码,
            page_登录记录: 操作留痕_登录记录_当前页码,
            pageSize登录: 操作留痕_登录每页数量,
            pageSize余额: 操作留痕_余额每页数量
        };


        const result = await POSTPHP(开发者UID, 开发者密码, 开发者Token, 获取API链接('api.php'), params);
        if (result.success) {
            const 余额变动数据 = result.data.余额变动.data;//操作留痕-余额变动组
            操作留痕_余额变动_总页数 = result.data.余额变动.totalPages;
            操作留痕_余额变动_总数量 = result.data.余额变动.total;
            操作留痕_余额变动_渲染表格(余额变动数据);
            
            
            const 登录日志数据 = result.data.登录日志.data;
            操作留痕_登录记录_总页数 = result.data.登录日志.totalPages;
            操作留痕_登录记录_总数量 = result.data.登录日志.total;
            操作留痕_登录日志_渲染表格(登录日志数据);
            
            
            

            
            操作留痕_余额变动_更新统计显示数据();
            
            
            
            
            
            
            if (操作留痕_加载动画) 操作留痕_加载动画.style.display = 'none';
            
        } else {
            alert('加载应用失败: ' + result.message, false);
            if (操作留痕_加载动画) 操作留痕_加载动画.style.display = 'none';
        }
        
   
}



function 操作留痕_余额变动_渲染表格(余额变动s) {
    const tbody = document.getElementById('操作留痕_余额变动_TableBody');
    if (!tbody) return;
    
    tbody.innerHTML = '';
    
    if (余额变动s.length === 0) {
        const emptyRow = document.createElement('tr');
        emptyRow.innerHTML = `
            <td colspan="6" style="text-align: center; padding: 60px 20px; color: #9ca3af;">
                <div style="font-size: 14px;">暂无余额变动记录</div>
            </td>
        `;
        tbody.appendChild(emptyRow);
        return;
    }
    
    余额变动s.forEach((余额变动) => {
        const row = document.createElement('tr');
        
        // 状态样式（仅成功/失败）
        const isSuccess = 余额变动.status === '成功';
        const statusBgColor = isSuccess ? '#e8f5e9' : '#ffebee';
        const statusTextColor = isSuccess ? '#2e7d32' : '#c62828';
        const statusIcon = isSuccess ? '✓' : '✗';
        const statusText = 余额变动.status || '-';
        
        // 金额正负样式
        const changeValue = 余额变动.balance_change || '0';
        const isPositive = changeValue.toString().startsWith('+');
        const changeColor = isPositive ? '#4caf50' : '#f44336';
        const changeSign = isPositive ? '+' : '';
        
        let displayValue = changeValue;
        if (!changeValue.startsWith('+') && !changeValue.startsWith('-') && changeValue !== '0') {
            displayValue = (isPositive ? '+' : '') + changeValue;
        }

        row.innerHTML = `
            <td style="padding: 14px 12px; color: #1e293b; font-size: 14px; border: none;">
                ${余额变动.ID || '-'}
            </td>
            <td style="padding: 14px 12px; color: #1e293b; font-size: 14px; border: none;">
                ${余额变动.action_name || '-'}
            </td>
            <td style="padding: 14px 12px; color: ${changeColor}; font-size: 14px; font-weight: 500; border: none;">
                ${displayValue}
            </td>
            <td style="padding: 14px 12px; color: #64748b; font-size: 13px; border: none;">
                ${余额变动.execute_time || '-'}
            </td>
            <td style="padding: 14px 12px; color: #64748b; font-size: 13px; border: none;">
                <span title="${余额变动.execute_ip_full || ''}">${余额变动.execute_ip || '-'}</span>
             </td>
            <td style="padding: 14px 12px; border: none;">
                <span style="display: inline-flex; align-items: center; gap: 6px; padding: 4px 12px; border-radius: 20px; font-size: 12px; font-weight: 500; background-color: ${statusBgColor}; color: ${statusTextColor};">
                    ${statusIcon} ${statusText}
                </span>
             </td>
        `;
        tbody.appendChild(row);
    });
}
function 操作留痕_登录日志_渲染表格(登录日志s) {
    const tbody = document.getElementById('操作留痕_登录日志_TableBody');
    if (!tbody) return;
    
    tbody.innerHTML = '';
    
    if (登录日志s.length === 0) {
        const emptyRow = document.createElement('tr');
        emptyRow.innerHTML = `
            <td colspan="3" style="text-align: center; padding: 60px 20px; color: #9ca3af;">
                <div style="font-size: 14px;">暂无登录记录</div>
            </td>
        `;
        tbody.appendChild(emptyRow);
        return;
    }
    
    // 获取今天的日期字符串 (YYYY-MM-DD)
    const today = new Date();
    const todayStr = `${today.getFullYear()}-${String(today.getMonth() + 1).padStart(2, '0')}-${String(today.getDate()).padStart(2, '0')}`;
    
    登录日志s.forEach((登录日志) => {
        const row = document.createElement('tr');
        
        // 判断是否为今天登录
        const loginDate = 登录日志.登录时间 ? 登录日志.登录时间.split(' ')[0] : '';
        const isToday = loginDate === todayStr;
        
        // 时间样式：今天登录高亮显示
        const timeColor = isToday ? '#e67e22' : '#64748b';
        const timeWeight = isToday ? '500' : '400';

        row.innerHTML = `
            <td style="padding: 14px 12px; color: #1e293b; font-size: 14px; border: none;">
                ${登录日志.ID || '-'}
            </td>
            <td style="padding: 14px 12px; color: #1e293b; font-size: 14px; border: none;">
                <span title="${登录日志.登录IP完整 || ''}">${登录日志.登录IP || '-'}</span>
            </td>
            <td style="padding: 14px 12px; color: ${timeColor}; font-size: 13px; font-weight: ${timeWeight}; border: none;">
                ${登录日志.登录时间 || '-'}${isToday ? ' <span style="color: #e67e22; font-size: 12px; margin-left: 8px;">(今日登录)</span>' : ''}
            </td>
        `;
        tbody.appendChild(row);
    });
}


